"""Where every generated file goes, and the README that describes them.

generate() is pure: it returns {relative path: text}. write() and check() are the
only functions that touch the disk, so the build and its --check mode share one
source of truth.
"""
from __future__ import annotations

from pathlib import Path

from . import tokens as t
from . import variants
from .marks import MARKS

ROOT = Path(__file__).resolve().parent.parent
LOGO_DIR = "logo"


def _logo_readme(per_product: dict[str, dict[str, str]]) -> str:
    lines = [
        "# logo/",
        "",
        "Generated by `build.py`. Do not edit by hand: change the kit and rebuild.",
        "",
        "One folder per product, the same file names in each. Those names are what the",
        "other repositories link to, so renaming one is a breaking change.",
        "",
    ]
    for key, mark in MARKS.items():
        lines += [f"## {mark.name}", "", mark.summary, "", f"Folder: `{LOGO_DIR}/{key}/`", "",
                  "| File | Use |", "| --- | --- |"]
        for name in per_product[key]:
            lines.append(f"| `{name}` | {variants.USAGE.get(name, '')} |")
        lines.append("")
    lines += ["## Colour", "",
              f"Orange is the only brand colour: `{t.ORANGE}`, shaded from `{t.ORANGE_LIGHT}` to `{t.ORANGE_DEEP}`.",
              "Everything else is ink, paper and greys.", ""]
    return "\n".join(lines)


def generate() -> dict[str, str]:
    out: dict[str, str] = {}
    per_product: dict[str, dict[str, str]] = {}
    for key, mark in MARKS.items():
        files = variants.files(mark)
        per_product[key] = files
        for name, content in files.items():
            out[f"{LOGO_DIR}/{key}/{name}"] = content
    out[f"{LOGO_DIR}/README.md"] = _logo_readme(per_product)
    return out


def existing(root: Path = ROOT) -> set[str]:
    base = root / LOGO_DIR
    if not base.exists():
        return set()
    return {p.relative_to(root).as_posix() for p in base.rglob("*") if p.is_file()}


def write(root: Path = ROOT) -> list[str]:
    """Write every generated file and remove stale ones. Returns what changed."""
    wanted = generate()
    changed: list[str] = []
    for rel, content in wanted.items():
        target = root / rel
        if target.exists() and target.read_text(encoding="utf-8") == content:
            continue
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(content, encoding="utf-8", newline="\n")
        changed.append(rel)
    for rel in sorted(existing(root) - set(wanted)):
        (root / rel).unlink()
        changed.append(f"{rel} (removed)")
    return changed


def check(root: Path = ROOT) -> list[str]:
    """Differences between the tree on disk and what the kit would generate."""
    wanted = generate()
    problems: list[str] = []
    for rel, content in wanted.items():
        target = root / rel
        if not target.exists():
            problems.append(f"missing: {rel}")
        elif target.read_text(encoding="utf-8") != content:
            problems.append(f"out of date: {rel}")
    problems += [f"stale: {rel}" for rel in sorted(existing(root) - set(wanted))]
    return problems
